    if (target_fd < 0) {
        perror("open target");
        return 1;
    }

    int repl_fd = open(replacement_file, O_RDONLY);
    if (repl_fd < 0) {
        perror("open replacement");
        close(target_fd);
        return 1;
    }

    struct stat st;
    if (fstat(repl_fd, &st) < 0) {
        perror("fstat");
        close(target_fd);
        close(repl_fd);
        return 1;
