    if (result < 0) {
        perror("splice");
        close(target_fd);
        close(repl_fd);
        return 1;
    }

    printf("Successfully overwrote %s with %s (%ld bytes)\n", target_file, replacement_file, result);

    close(target_fd);
    close(repl_fd);
    return 0;
}
